insert into reply (is_deleted, board_id, created_date, last_modified_date, member_id, parent_id, content, nickname) values (0, 36, '2026-08-01 23:21:55.158', '2026-08-01 23:21:55.158', 33, 67, '승인된 의하여 계승·발전과 의무교육은.', '지민.김');
insert into reply (is_deleted, board_id, created_date, last_modified_date, member_id, parent_id, content, nickname) values (0, 65, '2026-08-01 23:21:55.158', '2026-08-01 23:21:55.158', 19, 54, '국민은 보장하기 위하여.', '예은.박');
insert into reply (is_deleted, board_id, created_date, last_modified_date, member_id, parent_id, content, nickname) values (0, 40, '2026-08-01 23:21:55.158', '2026-08-01 23:21:55.158', 33, 51, '경우와 동일한 헌법에 승인된 민족문화의.', '지후.임');
insert into reply (is_deleted, board_id, created_date, last_modified_date, member_id, parent_id, content, nickname) values (0, 20, '2026-08-01 23:21:55.158', '2026-08-01 23:21:55.158', 39, 58, '자유를 의무교육은 국제법규는 무죄로 같은 국내법과.', '민서.신');
insert into reply (is_deleted, board_id, created_date, last_modified_date, member_id, parent_id, content, nickname) values (0, 18, '2026-08-01 23:21:55.158', '2026-08-01 23:21:55.158', 67, 53, '계승·발전과 가진다. 의하여 한다. 권리는 진흥하여야.', '현준.윤');
